@deralmas Do you recall why you added all this logic for `!GLAD_ENABLED` on Linux/Wayland?

Seems mostly related to #92663 though the `!GLAD_ENABLED` branch predates it.

There's quite a lot of code that can be removed if this is indeed unnecessary, so I'll leave it for a follow-up PR.

```diff
diff --git a/drivers/gles3/rasterizer_gles3.cpp b/drivers/gles3/rasterizer_gles3.cpp
index 46355ea71a..3b34c1e089 100644
--- a/drivers/gles3/rasterizer_gles3.cpp
+++ b/drivers/gles3/rasterizer_gles3.cpp
@@ -128,7 +128,7 @@ void RasterizerGLES3::gl_end_frame(bool p_swap_buffers) {
        }
 }

-#ifdef EGL_DEBUG_CALLBACK
+#if defined(EGL_DEBUG_CALLBACK) || defined(GLAD_ENABLED)
 static void GLAPIENTRY _gl_debug_print(GLenum source, GLenum type, GLuint id, GLenum severity, GLsizei length, const GLchar *message, const GLvoid *userParam) {
        // These are ultimately annoying, so removing for now.
        if (type == _EXT_DEBUG_TYPE_OTHER_ARB || type == _EXT_DEBUG_TYPE_PERFORMANCE_ARB || type == _EXT_DEBUG_TYPE_MARKER_ARB) {
@@ -179,7 +179,7 @@ static void GLAPIENTRY _gl_debug_print(GLenum source, GLenum type, GLuint id, GL

        ERR_PRINT(output);
 }
-#endif // EGL_DEBUG_CALLBACK
+#endif // EGL_DEBUG_CALLBACK || GLAD_ENABLED

 typedef void(GLAPIENTRY *DEBUGPROCARB)(GLenum source,
                GLenum type,
